// Generates registry/styles/fiori.css from SAP's official Horizon theme output.
// Nothing in the generated file is hand-tuned: every --sap* value comes from
// @sap-theming/theming-base-content. The 72 @font-face rules (from UI5 Web Components) go to a
// separate, optional registry/styles/fiori-font.css: the font files are not Apache-2.0 (see below).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs"
import { createRequire } from "node:module"
import { dirname, join } from "node:path"

const require = createRequire(import.meta.url)
const themingPkg = dirname(require.resolve("@sap-theming/theming-base-content/package.json"))
const themingVersion = JSON.parse(readFileSync(join(themingPkg, "package.json"), "utf8")).version
const baseLib = join(themingPkg, "content/Base/baseLib")
const ui5Dir = dirname(require.resolve("@ui5/webcomponents/package.json"))
// Component parameters come from both UI5 packages (main: inputs, lists…; fiori: ShellBar, Upload…).
const ui5ParamDirs = [ui5Dir, dirname(require.resolve("@ui5/webcomponents-fiori/package.json"))]

const THEMES = ["sap_horizon", "sap_horizon_dark", "sap_horizon_hcb", "sap_horizon_hcw"]
const DEFAULT_THEME = "sap_horizon"

// 72 has no CJK glyphs; append a Chinese stack before the generic fallback.
const CJK = `"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"`

function readVars(theme) {
  const css = readFileSync(join(baseLib, theme, "css_variables.css"), "utf8")
  const root = css.slice(css.indexOf(":root{") + ":root{".length)
  const vars = new Map()
  // Values never contain ";" except inside the metadata JSON, which we skip.
  for (const decl of root.split(";")) {
    const m = decl.match(/^\s*(--sap[A-Za-z0-9_-]+)\s*:\s*([\s\S]*?)\s*}?\s*$/)
    if (!m || m[1].startsWith("--sapThemeMetaData") || m[1].startsWith("--sapFontUrl")) continue
    let value = m[2].trim()
    if (/sans-serif\s*$/.test(value) && value.includes("Arial")) {
      value = value.replace(/,\s*sans-serif\s*$/, `, ${CJK}, sans-serif`)
    }
    vars.set(m[1], value)
  }
  return vars
}

function fontFaces() {
  const basePkg = dirname(require.resolve("@ui5/webcomponents-base/package.json", { paths: [ui5Dir] }))
  const js = readFileSync(join(basePkg, "dist/generated/css/FontFace.css.js"), "utf8")
  const css = js.slice(js.indexOf("`") + 1, js.lastIndexOf("`"))
  // Pin the CDN to the same theming-base-content version the tokens come from.
  return css
    .replace(/theming-base-content@[\d.]+/g, `theming-base-content@${themingVersion}`)
    .replace(/}/g, "}\n")
    .trim()
}

const themes = Object.fromEntries(THEMES.map((t) => [t, readVars(t)]))
const base = themes[DEFAULT_THEME]

const block = (selector, entries) =>
  `${selector} {\n${[...entries].map(([k, v]) => `  ${k}: ${v};`).join("\n")}\n}`

const out = []
out.push(`/*
 * Fiori (SAP Horizon) theme for shadcn/ui — GENERATED by scripts/generate-tokens.mjs, do not edit.
 * --sap* values: @sap-theming/theming-base-content@${themingVersion} (Apache-2.0, © SAP SE).
 * Themes: ${THEMES.join(", ")}. Switch with <html data-theme="...">.
 * Density: cozy by default, <html data-density="compact"> (or any subtree) for compact.
 * --fiori-* component params: @ui5/webcomponents theme parameters (Apache-2.0, © SAP SE).
 * WCR theme parameters, © SAP SE, Apache-2.0.
 * The 72 font is not included; it is the optional fiori-font.css (not Apache-2.0, see that file).
 */`)

out.push(block(`:root,\n[data-theme="${DEFAULT_THEME}"]`, base))
for (const t of THEMES.filter((t) => t !== DEFAULT_THEME)) {
  const diff = [...themes[t]].filter(([k, v]) => base.get(k) !== v)
  const scheme = t === "sap_horizon_hcw" ? "light" : "dark"
  out.push(block(`[data-theme="${t}"]`, [...diff, ["color-scheme", scheme]]))
}

// Component parameters (heights, paddings, value-state styling...) taken from UI5 Web Components'
// compiled theme parameters, renamed --_ui5_button_base_height -> --fiori-button-base-height.
// UI5 declares them per :host; we declare them on :root and every [data-theme]/[data-density]
// element so values that reference --sap* or density-dependent vars re-resolve in subtrees.
// All of them: components added later find their parameters already generated.
const COMPONENT_PARAMS = /^--_?ui5[_-]/
// UI5 has a few keys that differ only by "_" vs "-" (e.g. --_ui5_input_value_state_icon_display vs
// --_ui5-input-value-state-icon-display); the dash-prefixed spelling gets an "x-" marker to stay distinct.
const WCR_PARAMS = /^--_ui5wcr[_-]/
function rename(key) {
  const prefix = WCR_PARAMS.test(key) ? "--fiori-wcr-" : "--fiori-"
  const name = key.replace(/^--_?ui5(?:wcr)?/, "")
  return prefix + (name.startsWith("-") ? "x-" : "") + name.slice(1).replace(/_/g, "-").toLowerCase()
}

// WCR theme parameters, © SAP SE, Apache-2.0. Morning and Evening share
// sap_horizon; both high-contrast themes share sap_horizon_hc.
const wcrDist = join(dirname(require.resolve("@ui5/webcomponents-react/package.json")), "dist")
const readWcrTheme = (name) => readFileSync(join(wcrDist, "css/themes", `${name}.css`), "utf8")
const wcrParams = (css) => [...css.matchAll(/(--_ui5wcr[_-][\w-]+)\s*:\s*([^;}]+)/g)]
  .map(([, key, value]) => [key, value.trim()])
const wcrBase = wcrParams(readWcrTheme("base"))
const wcrHorizon = wcrParams(readWcrTheme("sap_horizon"))
const wcrHighContrast = wcrParams(readWcrTheme("sap_horizon_hc"))
const wcrProviderCss = readFileSync(join(wcrDist, "components/ThemeProvider/ThemeProvider.css.js"), "utf8")
const wcrDensityParams = (selector) => {
  const start = wcrProviderCss.indexOf(selector)
  if (start < 0) throw new Error(`Missing WCR density selector ${selector}`)
  return wcrParams(wcrProviderCss.slice(start + selector.length, wcrProviderCss.indexOf("}", start)))
}
const wcrCozy = wcrDensityParams(":root{")
const wcrCompact = wcrDensityParams("[data-ui5-compact-size]{")

function readComponentParams(theme) {
  const cozy = new Map(), compact = new Map()
  for (const dir of ui5ParamDirs) {
  const js = readFileSync(join(dir, "dist/generated/themes", theme, "parameters-bundle.css.js"), "utf8")
  const css = js.slice(js.indexOf("`") + 1, js.lastIndexOf("`"))
  for (const m of css.matchAll(/(@container style\(--ui5_content_density: compact\)\{)?:host\{([^}]*)\}/g)) {
    const target = m[1] ? compact : cozy
    for (const decl of m[2].split(";")) {
      const i = decl.indexOf(":")
      if (i < 0) continue
      const k = decl.slice(0, i).trim()
      if (COMPONENT_PARAMS.test(k)) target.set(k, decl.slice(i + 1).trim())
    }
  }
  }
  for (const [k, v] of [...wcrCozy, ...wcrBase, ...(theme.startsWith("sap_horizon_hc") ? wcrHighContrast : wcrHorizon)]) cozy.set(k, v)
  for (const [k, v] of wcrCompact) compact.set(k, v)
  return { cozy, compact }
}

const params = Object.fromEntries(THEMES.map((t) => [t, readComponentParams(t)]))
const known = new Set(Object.values(params).flatMap(({ cozy, compact }) => [...cozy.keys(), ...compact.keys()]))
const renamed = new Map()
for (const k of known) {
  const n = rename(k)
  if (renamed.has(n) && renamed.get(n) !== k) throw new Error(`param name collision: ${k} / ${renamed.get(n)} -> ${n}`)
  renamed.set(n, k)
}
const renameValue = (v) => v.replace(/var\((--[_a-zA-Z0-9-]+)/g, (all, ref) => (known.has(ref) ? `var(${rename(ref)}` : all))
const paramEntries = (map) => [...map].map(([k, v]) => [rename(k), renameValue(v)])

// Keys whose value (transitively) references a density-dependent key must be re-declared in the
// compact block, otherwise they'd inherit the value already resolved with cozy inputs.
function withDependents(cozy, overrides) {
  const keys = new Set(overrides.keys())
  let grew = true
  while (grew) {
    grew = false
    for (const [k, v] of cozy) {
      if (keys.has(k)) continue
      if ([...v.matchAll(/var\((--[_a-zA-Z0-9-]+)/g)].some((x) => keys.has(x[1]))) { keys.add(k); grew = true }
    }
  }
  return new Map([...keys].map((k) => [k, overrides.get(k) ?? cozy.get(k)]))
}

const baseParams = params[DEFAULT_THEME]
out.push(block(`:root,\n[data-theme],\n[data-density="cozy"]`, paramEntries(baseParams.cozy)))
out.push(block(`[data-density="compact"]`, paramEntries(withDependents(baseParams.cozy, baseParams.compact))))
for (const t of THEMES.filter((t) => t !== DEFAULT_THEME)) {
  const { cozy: own, compact } = params[t]
  // Keys this theme doesn't define at all (e.g. --_ui5_breadcrumbs_margin in the HC themes) are
  // unset in UI5; declare them `initial` so they don't inherit the default theme's value.
  const cozy = new Map([...own, ...[...baseParams.cozy.keys()].filter((k) => !own.has(k)).map((k) => [k, "initial"])])
  const cozyDiff = new Map([...cozy].filter(([k, v]) => baseParams.cozy.get(k) !== v))
  // The theme's cozy block outranks the generic [data-density="compact"] block, so a themed compact
  // block re-declares every density-dependent key (not just those whose value differs from base).
  const compactAll = withDependents(cozy, compact)
  for (const k of cozyDiff.keys()) if (!compactAll.has(k) && withDependents(baseParams.cozy, baseParams.compact).has(k)) compactAll.set(k, cozy.get(k))
  const compactDiff = cozyDiff.size ? compactAll : new Map()
  if (cozyDiff.size) out.push(block(`[data-theme="${t}"]`, paramEntries(cozyDiff)))
  if (compactDiff.size) out.push(block(`[data-theme="${t}"][data-density="compact"],\n[data-theme="${t}"] [data-density="compact"]`, paramEntries(compactDiff)))
}

// shadcn compatibility: any stock shadcn component installed next to these picks up Fiori colors.
// Exported as JSON too, so the registry item can hand it to the shadcn CLI as cssVars (otherwise
// `shadcn init` writes its neutral palette into the app's CSS after our imports).
export const SHADCN_VARS = {
  "radius": "var(--sapButton_BorderCornerRadius)",
  "background": "var(--sapBackgroundColor)",
  "foreground": "var(--sapTextColor)",
  "card": "var(--sapTile_Background)",
  "card-foreground": "var(--sapTile_TextColor)",
  "popover": "var(--sapGroup_ContentBackground)",
  "popover-foreground": "var(--sapTextColor)",
  "primary": "var(--sapButton_Emphasized_Background)",
  "primary-foreground": "var(--sapButton_Emphasized_TextColor)",
  "secondary": "var(--sapButton_Background)",
  "secondary-foreground": "var(--sapButton_TextColor)",
  "muted": "var(--sapNeutralBackground)",
  "muted-foreground": "var(--sapContent_LabelColor)",
  "accent": "var(--sapList_Hover_Background)",
  "accent-foreground": "var(--sapList_TextColor)",
  "destructive": "var(--sapButton_Negative_Background)",
  "border": "var(--sapGroup_ContentBorderColor)",
  "input": "var(--sapField_BorderColor)",
  "ring": "var(--sapContent_FocusColor)",
  "sidebar": "var(--sapShell_Navigation_Background)",
  "sidebar-foreground": "var(--sapShell_Navigation_TextColor)",
  "sidebar-primary": "var(--sapShell_Navigation_SelectedColor)",
  "sidebar-primary-foreground": "var(--sapContent_ContrastTextColor)",
  "sidebar-accent": "var(--sapShell_Navigation_Hover_Background)",
  "sidebar-accent-foreground": "var(--sapShell_Navigation_TextColor)",
  "sidebar-border": "var(--sapShell_BorderColor)",
  "sidebar-ring": "var(--sapContent_FocusColor)",
}
out.push(block(`:root,\n[data-theme]`, Object.entries(SHADCN_VARS).map(([k, v]) => [`--${k}`, v])))

mkdirSync("registry/styles", { recursive: true })
writeFileSync("registry/styles/fiori.css", out.join("\n\n") + "\n")

// The 72 font files ship inside the Apache-2.0 theming package, but each file's embedded license says
// "Copyright SAP SE. All rights reserved" with Monotype terms that forbid copying or redistribution.
// So the registry never bundles them, and the @font-face rules are an opt-in item (@petalo/fiori-font)
// that only points at SAP's npm copy on jsDelivr, the same URLs UI5 Web Components load.
// Without it, --sapFontFamily falls back to Arial / Helvetica / the CJK stack.
writeFileSync("registry/styles/fiori-font.css", `/*
 * SAP 72 font faces — GENERATED by scripts/generate-tokens.mjs, do not edit. OPTIONAL.
 * Loads the 72 font files from https://cdn.jsdelivr.net/npm/@sap-theming/theming-base-content@${themingVersion}
 * (the same URLs UI5 Web Components use). Nothing here is a copy of the font.
 * The font files are NOT covered by this project's Apache-2.0 license: their embedded license reads
 * "Copyright SAP SE. All rights reserved" plus Monotype terms. Check that your use of the 72 font is
 * permitted (for example under your SAP license) before you ship this file. Remove it and the theme
 * falls back to Arial / Helvetica. Loading it also makes browsers request fonts from jsDelivr.
 */
${fontFaces()}
`)
writeFileSync("registry/styles/shadcn-vars.json", JSON.stringify(SHADCN_VARS, null, 2) + "\n")

// Tailwind entry: @theme mapping + base layer. Kept separate so fiori.css stays framework-free.
writeFileSync("registry/styles/fiori-tailwind.css", `/* GENERATED by scripts/generate-tokens.mjs — Tailwind v4 bindings for fiori.css. */
@custom-variant dark (&:where([data-theme="sap_horizon_dark"], [data-theme="sap_horizon_dark"] *, [data-theme="sap_horizon_hcb"], [data-theme="sap_horizon_hcb"] *));
@custom-variant compact (&:where([data-density="compact"], [data-density="compact"] *));

@theme inline {
  --font-sans: var(--sapFontFamily);
  --font-mono: "72Mono", "72Monofull", ui-monospace, monospace;
  --radius-sm: var(--sapField_BorderCornerRadius);
  --radius-md: var(--sapButton_BorderCornerRadius);
  --radius-lg: var(--sapElement_BorderCornerRadius);
  --radius-xl: var(--sapTile_BorderCornerRadius);
  --shadow-fiori-0: var(--sapContent_Shadow0);
  --shadow-fiori-1: var(--sapContent_Shadow1);
  --shadow-fiori-2: var(--sapContent_Shadow2);
  --shadow-fiori-3: var(--sapContent_Shadow3);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

@layer base {
  * {
    border-color: var(--color-border);
  }
  html {
    font-family: var(--sapFontFamily);
    font-size: 16px;
  }
  body {
    background: var(--sapBackgroundColor);
    color: var(--sapTextColor);
    font-family: var(--sapFontFamily);
    font-size: var(--sapFontSize);
  }
}
`)

console.log(`component params: ${baseParams.cozy.size} cozy, ${baseParams.compact.size} compact overrides`)
const counts = THEMES.map((t) => `${t}=${themes[t].size}`).join(" ")
console.log(`fiori.css written (${counts})`)
